event: response.output_text.done
data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_01f48efca928fd6e016aeb2630bf7087d294715f8697fef0f9","logprobs":[],"output_index":0,"sequence_number":822,"text":"<title>Bean &amp; Bloom</title>\n<meta name=\"idea\" content=\"A cozy coffee menu with instant order totals and clear paths to checkout\">\n<header>\n  <h1>Bean &amp; Bloom</h1>\n  <p>Good coffee, made for your day.</p>\n  <nav aria-label=\"Main navigation\">\n    <a href=\"#\" data-action=\"Coffee menu with featured drinks and live order total\">Menu</a> ·\n    <a href=\"#\" data-action=\"Your coffee orders with recent purchases and order tracking\">Orders</a> ·\n    <a href=\"#\" data-action=\"Your Bean & Bloom account profile and saved preferences\">Profile</a>\n  </nav>\n</header>\n<main>\n  <h2>Popular today</h2>\n  <label for=\"size\">Drink size</label>\n  <select id=\"size\"><option value=\"0\">Small</option><option value=\"0.75\">Medium +$0.75</option><option value=\"1.25\">Large +$1.25</option></select>\n  <article>\n    <h3>Honey oat latte <small>$5.25</small></h3>\n    <p>Espresso, oat milk, a little local honey.</p>\n    <button data-action=\"Details for the Honey oat latte, including ingredients and customization options\">Details</button>\n    <button class=\"add\" data-name=\"Honey oat latte\" data-price=\"5.25\">Add to order</button>\n  </article>\n  <article>\n    <h3>Maple cold brew <small>$4.75</small></h3>\n    <p>Slow-steeped coffee with maple cream.</p>\n    <button data-action=\"Details for the Maple cold brew, including ingredients and customization options\">Details</button>\n    <button class=\"add\" data-name=\"Maple cold brew\" data-price=\"4.75\">Add to order</button>\n  </article>\n  <article>\n    <h3>Cardamom cappuccino <small>$4.50</small></h3>\n    <p>Velvety foam with a fragrant spice finish.</p>\n    <button data-action=\"Details for the Cardamom cappuccino, including ingredients and customization options\">Details</button>\n    <button class=\"add\" data-name=\"Cardamom cappuccino\" data-price=\"4.50\">Add to order</button>\n  </article>\n  <article>\n    <h3>Your order <small><span id=\"count\">0</span> items</small></h3>\n    <p id=\"summary\">Add a drink to get started.</p>\n    <p>Total: <strong id=\"total\">$0.00</strong></p>\n    <button data-action=\"Checkout screen for a Bean & Bloom coffee order with pickup time and payment options\">Checkout</button>\n    <button data-action=\"Edit your Bean & Bloom coffee order and adjust drink quantities\">Edit order</button>\n    <button data-action=\"Coffee menu with featured drinks and live order total\">Browse menu</button>\n  </article>\n</main>\n<script>\nlet items=[], size=0;\nconst money=n=>\"$\"+n.toFixed(2);\nfunction update(){\n  document.querySelector(\"#count\").textContent=items.length.toLocaleString();\n  document.querySelector(\"#total\").textContent=money(items.reduce((s,x)=>s+x.price+size,0));\n  document.querySelector(\"#summary\").textContent=items.length?items.map(x=>x.name).join(\", \"):\"Add a drink to get started.\";\n}\ndocument.querySelector(\"#size\").addEventListener(\"input\",e=>{size=Number(e.target.value);update()});\ndocument.querySelectorAll(\".add\").forEach(b=>b.addEventListener(\"click\",()=>{items.push({name:b.dataset.name,price:Number(b.dataset.price)});update()}));\n</script>"}

